}/* ============================
   PREMIUM HIGH-CLASS SPEC SHEET
   Clean Grid Layout – Mobile + Desktop
   ============================ */

/* Container */
.cc-size-chart {
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  margin-top: 20px;
}

/* Title */
#size-chart-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 15px;
  color: #222;
  text-transform: none;
}

/* Wrapper for table */
.cc-table-scroll {
  overflow-x: visible !important;
}

/* Main table */
.cc-size-table {
  width: 100% !important;
  border-collapse: collapse !important;
  border-radius: 12px;
  overflow: hidden;
  background: #fff;
  border: 1px solid #e6e6e6;
}

/* Header */
.cc-size-table thead th {
  background: #f8f8f8;
  padding: 12px;
  font-weight: 600;
  font-size: 14px;
  text-align: center;
  border-bottom: 1px solid #eee;
}

/* Body cells */
.cc-size-table tbody td {
  padding: 12px;
  font-size: 14px;
  color: #333;
  text-align: center;
  border-bottom: 1px solid #f0f0f0;
}

/* Last row cleaner */
.cc-size-table tbody tr:last-child td {
  border-bottom: none;
}

/* Hover effect */
.cc-size-table tbody tr:hover {
  background: #fafafa;
}

/* ===== MOBILE OPTIMIZED (no scroll, perfect fit) ===== */
@media (max-width: 640px) {

  /* Force proper width */
  .cc-size-table {
    width: 100% !important;
    display: table !important;
    min-width: 0 !important;
    table-layout: fixed !important;
  }

  /* Perfect alignment */
  .cc-size-table thead th,
  .cc-size-table tbody td {
    font-size: 13px !important;
    padding: 10px !important;
    word-break: break-word;
  }

  /* Remove scroll */
  .cc-table-scroll {
    overflow-x: hidden !important;
  }
}
